[102. Binary Tree Level Order Traversal](https://leetcode.com/problems/binary-tree-level-order-traversal/description/)
#Neetcode150

The for loop, make sure we use all the nodes in queue is used, therefore layer by layer, which we need in the question

```js
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @return {number[][]}
 */
var levelOrder = function(root) {
           let result = []
        const bfs = (root) => {
            if(!root) return result

            let queue = [root]

            while(queue.length){
                let layer = []
                let width = queue.length

                for(let i = 0; i<width; i++){
                    let node = queue.shift()


                        layer.push(node.val)
                        if(node.left) queue.push(node.left)
                        if(node.right) queue.push(node.right)

                }
                result.push(layer)
            }

            return result
        }

        return bfs(root)
};
```

[199. Binary Tree Right Side View](https://leetcode.com/problems/binary-tree-right-side-view/description/)

#Neetcode150 [#Tree](https://leetcode.com/problem-list/tree/)

Imagine a rays coming from right side horizontally and hitting a binary tree. 
The nodes which shines, should be returned as output.

This question is similar to [102. Binary Tree Level Order Traversal](https://leetcode.com/problems/binary-tree-level-order-traversal/description/)

As we still go layer by layer, but only add the node which is at the end of the layer

```js
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {TreeNode} root
 * @return {number[]}
 */
var rightSideView = function(root) {

    let result = []
    const bfs = (root) => {
        if(!root) return result

        let queue = [root]

        while(queue.length){
            let width = queue.length

            for(let i = 0; i<width; i++){

                let node = queue.shift()

                if(node.left) queue.push(node.left)
                if(node.right) queue.push(node.right)

                //since we want only last node from the layer
                //eg width = 3, we won't add when we are node 0, node 1, but node2
                //because its the last node
                //therefore 3-0= 3 No, 3-1 = 2 No, 3-2 = 1 Yes, add, since last node, of layer
                if (width - i > 1) continue;

                result.push(node.val)
            }
        }

        return result
    }

    return (bfs(root))
};
