```js
/**
 * Definition for a binary tree node.
 * function TreeNode(val, left, right) {
 *     this.val = (val===undefined ? 0 : val)
 *     this.left = (left===undefined ? null : left)
 *     this.right = (right===undefined ? null : right)
 * }
 */
/**
 * @param {number[]} preorder
 * @param {number[]} inorder
 * @return {TreeNode}
 */
var buildTree = function(preorder, inorder) {
  //Recursive Method 
  //Preorder has root first, then left, then right
  //Inorder, has left first, root and then right


  if(!preorder.length || !inorder.length){
    return null
  }

  let rootValue = preorder[0]
  let root = new TreeNode(rootValue)

  // we will split from root, since its inorder, we will get the left and right subtree from it and use to build further
  let mid = inorder.indexOf(rootValue)  

  root.left = buildTree(preorder.slice(1, mid+1), inorder.slice(0, mid))
  root.right = buildTree(preorder.slice(mid+1), inorder.slice(mid+1))

  return root
};



var buildTree = function(preorder, inorder) {
    //we will create map value -> indices for inorder, for O(1) lookup for split
    let map = new Map()
    for(let i = 0; i<inorder.length; i++){
        map.set(inorder[i], i)
    }

    //global preorder index, which increases, as it consist of root node
    let preIdx = 0
    const builder = (l, r) => {
        if(l > r) return null

        //root from preorder
        let rootValue = preorder[preIdx]
        preIdx++

        let root = new TreeNode(rootValue)

        //find the index where the tree/subtree root is in inorder, to bisect it
        let mid = map.get(rootValue)

        //left subtree
        root.left = builder(l, mid-1)
        //right subtree
        root.right = builder(mid+1, r)

        return root
    }

    return builder(0, inorder.length - 1)
