/**
 * Definition for a binary tree node.
 * function TreeNode(val) {
 *     this.val = val;
 *     this.left = this.right = null;
 * }
 */

/**
 * Encodes a tree to a single string.
 *
 * @param {TreeNode} root
 * @return {string}
 */
var serialize = function(root) {
    let ser = []

//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~  
    //USING PREORDER DFS
    const dfs = (node) => {
        if(!node){
            ser.push("#")
            return null
        }

        ser.push(node.val)
        dfs(node.left)
        dfs(node.right)

    }

//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
    //USING BFS
    const bfs = (root) => {
        if(!root){
            ser.push("#")
            return
        }

        let queue = [root]

        while(queue.length){
            let node = queue.shift()

            if(node){
                ser.push(node.val)
                queue.push(node.left)
                queue.push(node.right)
            }
            else{
                ser.push("#")
            }
        }

    }
    //dfs(root)
    bfs(root)

    return ser.join(",")
};

/**
 * Decodes your encoded data to tree.
 *
 * @param {string} data
 * @return {TreeNode}
 */
var deserialize = function(data) {


    let deser = data.split(",")

//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
    //PREORDER CONTINUE
    let idx = 0

    const buildTree = () => {
        if(deser[idx] === "#"){
            idx++
            return null
        }

        let root = new TreeNode(Number(deser[idx]))
        idx++

        root.left = buildTree()
        root.right = buildTree()


        return root
    }

    //return buildTree()


//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~
    //BFS CONTINUE
    const bfsBuildTree = () => {
        if(data === "#") return null
        let deser = data.split(",")

        let i = 0
        let root = new TreeNode(Number(deser[i]))
        i++

        let queue = [root]

        while(queue.length){
            let node = queue.shift()

            if(deser[i] !== "#"){
                node.left = new TreeNode(Number(deser[i]))
                queue.push(node.left)
            }
            i++

            if(deser[i] !== "#"){
                node.right = new TreeNode(Number(deser[i]))
                queue.push(node.right)
            }
            i++
        }

        return root
    }

    return bfsBuildTree()
};

/**
 * Your functions will be called as such:
 * deserialize(serialize(root));
 */
