/**
 * @param {string} s
 * @param {string} queryCharacters
 * @param {number[]} queryIndices
 * @return {number[]}
 */
var longestRepeating = function(s, queryCharacters, queryIndices) {

    class SegmentTree {
        constructor(s){
            this.s = s
            this.segTree = Array(s.length * 4).fill(null)
        }

        merge(LEFT, RIGHT){

            let parentL = LEFT.leftL
            let parentR = RIGHT.rightL

            let maxLength = Math.max(LEFT.maxLength, RIGHT.maxLength)

            if(LEFT.rightChar === RIGHT.leftChar){
                //WHOLE Left MATCHES
                //BBB + BBC= BBBBBC.   //(no pun intended) 
                if(LEFT.leftL === LEFT.totalL){
                    parentL = LEFT.leftL + RIGHT.leftL 
                }
                //WHOLE Right matches
                //BC + CCC = BCCCC
                if(RIGHT.rightL === RIGHT.totalL){
                    parentR = RIGHT.rightL + LEFT.rightL
                }

                //across whole joined word
                maxLength = Math.max(maxLength, LEFT.rightL + RIGHT.leftL)
            }

            return {
                leftChar: LEFT.leftChar,
                rightChar : RIGHT.rightChar,
                leftL: parentL,
                rightL : parentR,
                totalL: LEFT.totalL + RIGHT.totalL,
                maxLength: maxLength
            }
        }

        buildTree(i, left, right){
            if(left === right){
                this.segTree[i] = {
                    leftChar: this.s[left],
                    rightChar: this.s[right],
                    leftL:1,
                    rightL:1,
                    totalL:1,
                    maxLength:1

                }
                return
            }

            let mid = Math.floor((left + right) / 2)

            this.buildTree(2*i+1, left, mid)
            this.buildTree(2*i+2, mid+1, right)

            let LEFT = this.segTree[2*i+1]
            let RIGHT = this.segTree[2*i+2]

            this.segTree[i] = this.merge(LEFT,RIGHT)

        }

        updateTree(idx, val, i, left, right){
            if(left === right){
                this.segTree[i] = {
                    leftChar: val,
                    rightChar: val,
                    leftL:1,
                    rightL:1,
                    totalL:1,
                    maxLength:1
                }
                return
            }

            let mid = Math.floor((left + right) / 2)

            if(idx <= mid){
                this.updateTree(idx, val, 2*i+1, left, mid)
            }else{
                this.updateTree(idx, val, 2*i+2, mid+1, right)
            }

            let LEFT = this.segTree[2*i+1]
            let RIGHT = this.segTree[2*i+2]

            this.segTree[i] = this.merge(LEFT, RIGHT)
        }

        //after all build and update, the root will have the answer

    }

    const segTree = new SegmentTree(s)
    segTree.buildTree(0, 0, s.length-1)
    let result = []
    for(let i = 0; i<queryIndices.length;i++){
        segTree.updateTree(queryIndices[i], queryCharacters[i], 0, 0, s.length-1)
        result.push(segTree.segTree[0].maxLength)
    }

    return result
};

