/**
 * @param {number[]} stones
 * @return {boolean}
 */
var stoneGameIX = function(stones) {
    const count = [0, 0, 0];

    // Count stones based on remainder when divided by 3
    for (const stone of stones) {
        count[stone % 3]++;
    }

    // If the number of remainder-0 stones is even,
    // their effect on the turn cancels out.
    // Alice wins iff there is at least one remainder-1
    // and at least one remainder-2 stone.
    if (count[0] % 2 === 0) {
        return count[1] > 0 && count[2] > 0;
    }

    // When count[0] is odd, Alice can win
    // if one of the following is possible.
    return Math.abs(count[1] - count[2]) > 2;
};
