/**
 * @param {number[]} stoneValue
 * @return {number}
 */
var stoneGameV = function(stoneValue) {
    let n = stoneValue.length

    let prefix = Array(n + 1).fill(0)

    for(let i = 0; i<n; i++){
        prefix[i+1] = prefix[i] + stoneValue[i]
    }

    let getSum = (l,r) => {
        return prefix[r+1] - prefix[l]
    }

    //dp[l][r] = maxscore
    const dp = Array.from({length : n} , () => Array(n).fill(-1))

    const topDown = (l, r) => {

        if(l === r) return 0

        if(dp[l][r] !== -1) return dp[l][r]

        let best = 0

        for(let k = l; k < r; k++){
            const leftSum = getSum(l, k)
            const rightSum = getSum(k+1, r)

            if(leftSum < rightSum){
                best = Math.max(best, leftSum + topDown(l, k))
            }

            else if(rightSum < leftSum){
                best = Math.max(best, rightSum + topDown(k+1 , r))
            }

            else{
                best = Math.max(best, leftSum + Math.max(
                    topDown(l, k), 
                    topDown(k+1, r)
                ))
            }
        }

        dp[l][r] = best

        return best
    }

    return topDown(0, n-1)
};
