/**
 * @param {number} n
 * @param {number[][]} reservedSeats
 * @return {number}
 */
var maxNumberOfFamilies = function(n, reservedSeats) {
    let reserved = new Map()


    for(let [row, col] of reservedSeats){
        if(!reserved.has(row)){
            reserved.set(row, new Set())
        }

        reserved.get(row).add(col)
    }

    //no res row, can take atmost 2 fams.
    //n - map size will give us the number of unreserved rows.
    let noRes = (n - reserved.size) * 2;

    const groupA = new Set([2, 3, 4, 5]);
    const groupB = new Set([4, 5, 6, 7]);
    const groupC = new Set([6, 7, 8, 9]);

    let ans = 0
    for(let [row, seats] of reserved){
        let checkA = true, checkB = true, checkC = true
        for(let seat of seats){
            if(groupA.has(seat)) checkA = false

            if(groupB.has(seat)) checkB = false

            if(groupC.has(seat)) checkC = false
        }

        if(checkA && checkC){
            ans+= 2

        }

        else if(checkA || checkB || checkC){
            ans+= 1

        }
    }

    return noRes + ans

};
```
